body.raw:
fields id,name,slug,summary,url,updated_at,first_release_date,
  game_type.type,game_status.status,cover.image_id,
  genres.name,themes.name,platforms.name,
  involved_companies.company.name,involved_companies.developer,involved_companies.publisher;
where id = {{igdbGameId}};
limit 1;

fields game_id,hastily,normally,completely,count;
where game_id = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}};

fields game,platform.name,campaigncoop,onlinecoop,onlinecoopmax,offlinecoop,offlinecoopmax,onlinemax,offlinemax,splitscreen;
where game = {{igdbMultiplayerGameId}};
sort id asc; limit {{igdbPageSize}};

fields id,game.id,game.name,date,human,y,m,d,date_format.format,platform.id,platform.name,release_region.id,release_region.region,status.name;
where date >= {{igdbFromEpoch}} & date < {{igdbToEpoch}};
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields id,game.id,game.name,date,human,y,m,d,date_format.format,platform.id,platform.name,release_region.id,release_region.region,status.name;
where date >= {{igdbNowEpoch}} & date < {{igdbToEpoch}} & platform = {{igdbPlatformId}};
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields id,game.id,game.name,date,human,y,m,d,date_format.format,platform.id,platform.name,release_region.id,release_region.region,status.name;
where game = {{igdbGameId}} & platform = {{igdbPlatformId}} & release_region = {{igdbReleaseRegionId}};
sort id asc; limit {{igdbPageSize}};

fields name,genres.id,genres.name,themes.name,game_modes.name;
where id = {{igdbGameId}};
limit 1;

fields game,company.id,company.name,developer,publisher,porting,supporting;
where game = {{igdbGameId}} & (developer = true | publisher = true);
sort id asc; limit {{igdbPageSize}};

fields id,name,description,country,parent.name,logo.image_id,url;
where id = {{igdbCompanyId}};
limit 1;

fields id,name,game_type.type,cover.image_id;
where involved_companies.company = {{igdbCompanyId}} & involved_companies.developer = true;
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields id,game,image_id,width,height,url;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields id,game,image_id,width,height,url;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields id,game,image_id,width,height,url;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields game,name,video_id;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}};

fields game,name,comment;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}};

fields game,name,region.id,region.name,region.identifier,cover.image_id;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}};

fields game,language.id,language.name,language.locale,language_support_type.name;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}};

fields name,age_ratings.organization.name,age_ratings.rating_category.rating,age_ratings.synopsis;
where id = {{igdbGameId}};
limit 1;

fields id,organization.name,rating_category.rating,synopsis,rating_cover_url;
where id = ({{igdbAgeRatingIds}});
sort id asc; limit {{igdbPageSize}};

fields name,rating,rating_count,aggregated_rating,aggregated_rating_count;
where id = {{igdbGameId}};
limit 1;

fields game_id,value,popularity_type.name,external_popularity_source.name,calculated_at;
where popularity_type = {{igdbPopularityTypeId}};
sort value desc; limit {{igdbPageSize}};

fields id,name,cover.image_id,game_type.type;
where id = ({{igdbPopularGameIds}});
sort id asc; limit {{igdbPageSize}};

fields name,collections.id,collections.name,franchise.id,franchise.name,franchises.id,franchises.name;
where id = {{igdbGameId}};
limit 1;

fields id,name,slug,type.name,url;
where id = {{igdbCollectionId}};
limit 1;

fields id,name,slug,url;
where id = {{igdbFranchiseId}};
limit 1;

fields id,name,game_type.type,first_release_date;
where collections = {{igdbCollectionId}};
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields id,name,game_type.type;
where franchise = {{igdbFranchiseId}} | franchises = {{igdbFranchiseId}};
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields name,parent_game.name,version_parent.name,dlcs.name,expansions.name,standalone_expansions.name,expanded_games.name,remakes.name,remasters.name,ports.name;
where id = {{igdbGameId}};
limit 1;

fields id,name,game_type.type,parent_game.id;
where parent_game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}}; offset {{igdbOffset}};

fields name,similar_games.id,similar_games.name;
where id = {{igdbGameId}};
limit 1;

fields game,url,trusted,type.type;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}};

fields game,name,uid,url,platform.name,external_game_source.name,game_release_format.format;
where game = {{igdbGameId}};
sort id asc; limit {{igdbPageSize}};

search "{{igdbSearchTerm}}";
fields id,name,game_type.type,version_parent.name,platforms.name,first_release_date;
where version_parent = null;
limit {{igdbPageSize}};

search "{{igdbGlobalSearchTerm}}";
fields name,game.id,game.name,collection.name,platform.name,theme.name,character.name;
limit {{igdbPageSize}};

fields id,name,updated_at;
where id > {{igdbAfterGameId}};
sort id asc; limit {{igdbPageSize}};

query games "card" {
  fields name,summary,cover.image_id,genres.name;
  where id = {{igdbGameId}}; limit 1;
};
query release_dates "releases" {
  fields game,platform.name,release_region.region,date,date_format.format,status.name;
  where game = {{igdbGameId}}; sort id asc; limit {{igdbPageSize}};
};
query language_supports "languages" {
  fields language.name,language_support_type.name;
  where game = {{igdbGameId}}; sort id asc; limit {{igdbPageSize}};
};
query game_time_to_beats "duration" {
  fields game_id,hastily,normally,completely,count;
  where game_id = {{igdbGameId}}; sort id asc; limit {{igdbPageSize}};
};
